1	package embedding
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net"
11		"net/http"
12		"net/url"
13		"os"
14		"strings"
15		"time"
16	
17		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
18	)
19	
20	const (
21		maxErrorBodyBytes     = 4096
22		defaultTimeoutSeconds = 10
23		baseRetryDelay        = 50 * time.Millisecond
24		maxRetryDelay         = 500 * time.Millisecond
25	)
26	
27	type OpenAICompatibleConfig struct {
28		BaseURL           string
29		Model             string
30		APIKeyEnv         string
31		TimeoutSeconds    int
32		MaxRetries        int
33		Dimensions        int
34		ExpectedDimension int
35		HTTPClient        *http.Client
36	}
37	
38	type OpenAICompatibleProvider struct {
39		endpoint          string
40		model             string
41		apiKeyEnv         string
42		timeout           time.Duration
43		maxRetries        int
44		dimensions        int
45		expectedDimension int
46		client            *http.Client
47	}
48	
49	type embeddingsRequest struct {
50		Model      string   `json:"model"`
51		Input      []string `json:"input"`
52		Dimensions int      `json:"dimensions,omitempty"`
53	}
54	
55	type embeddingsResponse struct {
56		Data  []embeddingDatum `json:"data"`
57		Error *providerError   `json:"error,omitempty"`
58	}
59	
60	type embeddingDatum struct {
61		Index     int       `json:"index"`
62		Embedding []float64 `json:"embedding"`
63	}
64	
65	type providerError struct {
66		Message string `json:"message"`
67		Type    string `json:"type,omitempty"`
68		Code    string `json:"code,omitempty"`
69	}
70	
71	func NewOpenAICompatibleProvider(cfg OpenAICompatibleConfig) (*OpenAICompatibleProvider, error) {
72		endpoint, err := embeddingsEndpoint(cfg.BaseURL)
73		if err != nil {
74			return nil, err
75		}
76		model := strings.TrimSpace(cfg.Model)
77		if model == "" {
78			return nil, fmt.Errorf("embedding endpoint model is required for backend %q", config.EmbeddingBackendOpenAICompatible)
79		}
80		if cfg.ExpectedDimension > 0 && cfg.Dimensions > 0 && cfg.ExpectedDimension != cfg.Dimensions {
81			return nil, fmt.Errorf("embedding endpoint dimensions (%d) must match target_dimension (%d)", cfg.Dimensions, cfg.ExpectedDimension)
82		}
83		if cfg.TimeoutSeconds < 0 {
84			return nil, fmt.Errorf("embedding endpoint timeout_seconds must be non-negative")
85		}
86	
87		timeoutSeconds := cfg.TimeoutSeconds
88		if timeoutSeconds == 0 {
89			timeoutSeconds = defaultTimeoutSeconds
90		}
91		timeout := time.Duration(timeoutSeconds) * time.Second
92		client := cfg.HTTPClient
93		if client == nil {
94			client = &http.Client{Timeout: timeout}
95		} else if client.Timeout == 0 && timeout > 0 {
96			copyClient := *client
97			copyClient.Timeout = timeout
98			client = &copyClient
99		}
100	
101		return &OpenAICompatibleProvider{
102			endpoint:          endpoint,
103			model:             model,
104			apiKeyEnv:         strings.TrimSpace(cfg.APIKeyEnv),
105			timeout:           timeout,
106			maxRetries:        max(0, cfg.MaxRetries),
107			dimensions:        cfg.Dimensions,
108			expectedDimension: cfg.ExpectedDimension,
109			client:            client,
110		}, nil
111	}
112	
113	func (p *OpenAICompatibleProvider) Embed(ctx context.Context, text string) ([]float32, error) {
114		embeddings, err := p.EmbedBatch(ctx, []string{text})
115		if err != nil {
116			return nil, err
117		}
118		return embeddings[0], nil
119	}
120	
121	func (p *OpenAICompatibleProvider) EmbedBatch(ctx context.Context, texts []string) ([][]float32, error) {
122		if len(texts) == 0 {
123			return [][]float32{}, nil
124		}
125		apiKey, err := p.resolveAPIKey()
126		if err != nil {
127			return nil, err
128		}
129	
130		var lastErr error
131		attempts := p.maxRetries + 1
132		for attempt := 1; attempt <= attempts; attempt++ {
133			embeddings, err := p.embedBatchOnce(ctx, texts, apiKey)
134			if err == nil {
135				return embeddings, nil
136			}
137			lastErr = err
138			if !shouldRetryEmbeddingError(err) || attempt == attempts {
139				break
140			}
141			if err := waitBeforeRetry(ctx, attempt); err != nil {
142				lastErr = err
143				break
144			}
145		}
146		if isTimeoutError(lastErr) {
147			return nil, fmt.Errorf("embedding provider request timed out after %d attempt(s): %w", attempts, lastErr)
148		}
149		return nil, fmt.Errorf("embedding provider request failed after %d attempt(s): %w", attempts, lastErr)
150	}
151	
152	func waitBeforeRetry(ctx context.Context, attempt int) error {
153		delay := baseRetryDelay << max(0, attempt-1)
154		if delay > maxRetryDelay {
155			delay = maxRetryDelay
156		}
157		timer := time.NewTimer(delay)
158		defer timer.Stop()
159		select {
160		case <-timer.C:
161			return nil
162		case <-ctx.Done():
163			return ctx.Err()
164		}
165	}
166	
167	func (p *OpenAICompatibleProvider) Dimension() int {
168		if p.expectedDimension > 0 {
169			return p.expectedDimension
170		}
171		return p.dimensions
172	}
173	
174	func (p *OpenAICompatibleProvider) Backend() string {
175		return config.EmbeddingBackendOpenAICompatible
176	}
177	
178	func (p *OpenAICompatibleProvider) embedBatchOnce(ctx context.Context, texts []string, apiKey string) ([][]float32, error) {
179		body, err := json.Marshal(embeddingsRequest{Model: p.model, Input: texts, Dimensions: p.dimensions})
180		if err != nil {
181			return nil, err
182		}
183	
184		attemptCtx := ctx
185		var cancel context.CancelFunc
186		if p.timeout > 0 {
187			attemptCtx, cancel = context.WithTimeout(ctx, p.timeout)
188		}
189		if cancel != nil {
190			defer cancel()
191		}
192	
193		req, err := http.NewRequestWithContext(attemptCtx, http.MethodPost, p.endpoint, bytes.NewReader(body))
194		if err != nil {
195			return nil, err
196		}
197		req.Header.Set("Content-Type", "application/json")
198		if apiKey != "" {
199			req.Header.Set("Authorization", "Bearer "+apiKey)
200		}
201	
202		resp, err := p.client.Do(req)
203		if err != nil {
204			return nil, err
205		}
206		defer resp.Body.Close()
207	
208		if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
209			return nil, responseError(resp)
210		}
211	
212		var decoded embeddingsResponse
213		if err := json.NewDecoder(resp.Body).Decode(&decoded); err != nil {
214			return nil, fmt.Errorf("decode embedding response: %w", err)
215		}
216		if decoded.Error != nil && decoded.Error.Message != "" {
217			return nil, fmt.Errorf("embedding provider error: %s", decoded.Error.Message)
218		}
219		return p.parseEmbeddings(decoded.Data, len(texts))
220	}
221	
222	func (p *OpenAICompatibleProvider) parseEmbeddings(data []embeddingDatum, expectedCount int) ([][]float32, error) {
223		if len(data) != expectedCount {
224			return nil, fmt.Errorf("embedding provider returned %d embedding(s), expected %d", len(data), expectedCount)
225		}
226	
227		result := make([][]float32, expectedCount)
228		for sequentialIndex, item := range data {
229			index, err := resolveEmbeddingIndex(item, sequentialIndex, expectedCount)
230			if err != nil {
231				return nil, err
232			}
233			if result[index] != nil {
234				return nil, fmt.Errorf("embedding provider returned duplicate embedding index %d", index)
235			}
236			converted, err := p.convertEmbedding(item.Embedding)
237			if err != nil {
238				return nil, fmt.Errorf("embedding index %d: %w", index, err)
239			}
240			result[index] = converted
241		}
242		if err := ensureCompleteEmbeddings(result); err != nil {
243			return nil, err
244		}
245		return result, nil
246	}
247	
248	func resolveEmbeddingIndex(item embeddingDatum, sequentialIndex int, expectedCount int) (int, error) {
249		index := item.Index
250		if expectedCount == 1 && index == 0 {
251			return 0, nil
252		}
253		if index == 0 && sequentialIndex > 0 {
254			index = sequentialIndex
255		}
256		if index < 0 || index >= expectedCount {
257			return 0, fmt.Errorf("embedding provider returned invalid embedding index %d", item.Index)
258		}
259		return index, nil
260	}
261	
262	func ensureCompleteEmbeddings(result [][]float32) error {
263		for i, embedding := range result {
264			if embedding == nil {
265				return fmt.Errorf("embedding provider omitted embedding index %d", i)
266			}
267		}
268		return nil
269	}
270	
271	func (p *OpenAICompatibleProvider) convertEmbedding(values []float64) ([]float32, error) {
272		if len(values) == 0 {
273			return nil, fmt.Errorf("empty embedding vector")
274		}
275		if p.expectedDimension > 0 && len(values) != p.expectedDimension {
276			return nil, fmt.Errorf("embedding dimension mismatch: got %d, want %d", len(values), p.expectedDimension)
277		}
278		embedding := make([]float32, len(values))
279		for i, value := range values {
280			embedding[i] = float32(value)
281		}
282		return embedding, nil
283	}
284	
285	func (p *OpenAICompatibleProvider) resolveAPIKey() (string, error) {
286		if p.apiKeyEnv == "" {
287			return "", nil
288		}
289		value := os.Getenv(p.apiKeyEnv)
290		if value == "" {
291			return "", fmt.Errorf("embedding API key env %q is not set", p.apiKeyEnv)
292		}
293		return value, nil
294	}
295	
296	func embeddingsEndpoint(baseURL string) (string, error) {
297		baseURL = strings.TrimSpace(baseURL)
298		if baseURL == "" {
299			return "", fmt.Errorf("embedding endpoint base_url is required for backend %q", config.EmbeddingBackendOpenAICompatible)
300		}
301		parsed, err := url.Parse(baseURL)
302		if err != nil {
303			return "", fmt.Errorf("invalid embedding endpoint base_url %q: %w", baseURL, err)
304		}
305		if parsed.Scheme == "" || parsed.Host == "" {
306			return "", fmt.Errorf("embedding endpoint base_url %q must include scheme and host", baseURL)
307		}
308		path := strings.TrimRight(parsed.Path, "/")
309		if !strings.HasSuffix(path, "/embeddings") {
310			path += "/embeddings"
311		}
312		parsed.Path = path
313		parsed.RawQuery = ""
314		return parsed.String(), nil
315	}
316	
317	type embeddingHTTPError struct {
318		statusCode int
319		message    string
320		retryable  bool
321	}
322	
323	func (e *embeddingHTTPError) Error() string {
324		return e.message
325	}
326	
327	func responseError(resp *http.Response) error {
328		body, _ := io.ReadAll(io.LimitReader(resp.Body, maxErrorBodyBytes))
329		bodyText := strings.TrimSpace(string(body))
330		if bodyText == "" {
331			bodyText = http.StatusText(resp.StatusCode)
332		}
333		message := fmt.Sprintf("embedding provider returned status %d: %s", resp.StatusCode, bodyText)
334		if resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden {
335			message = fmt.Sprintf("embedding provider authentication failed with status %d: %s", resp.StatusCode, bodyText)
336		}
337		return &embeddingHTTPError{
338			statusCode: resp.StatusCode,
339			message:    message,
340			retryable:  resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode >= http.StatusInternalServerError,
341		}
342	}
343	
344	func shouldRetryEmbeddingError(err error) bool {
345		var httpErr *embeddingHTTPError
346		if errors.As(err, &httpErr) {
347			return httpErr.retryable
348		}
349		return isTimeoutError(err) || isTemporaryNetworkError(err)
350	}
351	
352	func isTimeoutError(err error) bool {
353		if errors.Is(err, context.DeadlineExceeded) {
354			return true
355		}
356		var netErr net.Error
357		return errors.As(err, &netErr) && netErr.Timeout()
358	}
359	
360	func isTemporaryNetworkError(err error) bool {
361		var netErr net.Error
362		return errors.As(err, &netErr) && netErr.Temporary()
363	}
364

