1	package config
2	
3	import "strings"
4	
5	const (
6		EmbeddingBackendCandle           = "candle"
7		EmbeddingBackendOpenVINO         = "openvino"
8		EmbeddingBackendOpenAICompatible = "openai_compatible"
9	
10		EmbeddingModelTypeQwen3  = "qwen3"
11		EmbeddingModelTypeRemote = "remote"
12	)
13	
14	// EmbeddingEndpointConfig defines an external embedding provider endpoint.
15	type EmbeddingEndpointConfig struct {
16		BaseURL        string `yaml:"base_url,omitempty"`
17		Model          string `yaml:"model,omitempty"`
18		APIKeyEnv      string `yaml:"api_key_env,omitempty"`
19		TimeoutSeconds int    `yaml:"timeout_seconds,omitempty"`
20		MaxRetries     int    `yaml:"max_retries,omitempty"`
21		Dimensions     int    `yaml:"dimensions,omitempty"`
22	}
23	
24	func (e EmbeddingModels) EmbeddingBackend() string {
25		backend := normalizeEmbeddingBackend(e.EmbeddingConfig.Backend)
26		if backend != "" {
