		t.Fatalf("dimensions = %d, want 2", req.Dimensions)
	}
	if len(req.Input) != 2 || req.Input[0] != "hello" || req.Input[1] != "world" {
		t.Fatalf("input = %#v, want hello/world", req.Input)
	}
}

